insert into pajang_private.question_catalog(id,occasion,edition,turn,prompt,samples) values
  (12001,'spring',1,0,'꽃샘추위에 봄나들이 계획을 살짝 바꾼다면 뭘 남겨 둘까요?',array['햇볕 드는 창가에서 딸기는 먹어요.', '목도리를 두르고 나무 한 그루만 봐요.', '따뜻한 차에 나들이 간식을 곁들여요.']),
  (12002,'spring',1,1,'새싹 앞에 둘이 이름표를 꽂는다면 어떤 글을 적을까요?',array['첫 잎의 모양을 본떠 작은 하트를 그려요.', '먼저 알아본 사람의 별명을 붙여요.', '며칠 뒤 다시 만날 날짜를 적어요.']),
  (12003,'spring',1,2,'겨울 외투를 정리하다 작년 봄의 영수증을 찾으면요?',array['그날을 떠올리게 한 메뉴를 얘기해요.', '뒷면에 올해 가 보고 싶은 곳을 써요.', '빛바랜 숫자가 예뻐서 책갈피로 써요.']),
  (12004,'spring',1,3,'냉이랑 달래를 처음 맛보는 사람에게 봄 향을 어떻게 소개해요?',array['냉이 된장국을 작은 국자에 떠 줘요.', '달래 한 줄기를 살짝 비벼 향을 맡아요.', '간장에 잘게 썰어 밥에 조금 얹어요.']),
  (12005,'spring',1,4,'꽃잎이 흩날리는 날 서로를 웃게 할 사진 제목을 붙인다면요?',array['오늘의 주연은 머리에 붙은 분홍 점.', '바람 감독님, 한 번 더 부탁해요.', '둘이서 찍으려다 나무만 나온 날.']),
  (12006,'spring',1,5,'봄비가 막 그친 골목에서 둘이 아주 작게 귀를 기울인다면요?',array['차양 끝에서 한 박자씩 떨어지는 물이요.', '젖은 우산이 탁탁 접히는 소리요.', '새들이 서로 다른 음으로 우는 소리요.']),
  (12007,'spring',1,6,'봄 소풍 도시락을 나누는데 바람에 냅킨이 날아가면요?',array['제 빈 통에 남은 냅킨부터 넣어요.', '한 장만 주워 와서 바람 방향을 읽어요.', '다음엔 손수건을 챙기자고 약속해요.']),
  (12008,'spring',1,7,'겹겹이 핀 봄꽃을 종이로 함께 만든다면 나는 무슨 담당인가요?',array['색종이를 꽃잎 크기로 맞춰 잘라요.', '가운데 꽃술을 유난히 정교하게 말아요.', '어울리는 단어를 줄기에 적어 줘요.']),
  (12009,'spring',1,8,'연둣빛 그늘에서 서로 읽어 줄 만한 글은 어떤 글인가요?',array['나뭇잎 소리 사이로 들릴 짧은 동시요.', '둘 다 따라 웃을 만한 여행 실수담이요.', '아무 데나 펼쳐 읽어도 좋은 식물 도감이요.']),
  (12010,'spring',1,9,'장미가 한창인 길에서 색 이름을 새로 지으면 뭐가 나올까요?',array['갓 자른 수박 속분홍이요.', '해 질 녘 벽돌 담장 빨강이요.', '바닐라 아이스크림 끝물 흰색이요.']),
  (12011,'spring',1,10,'봄볕에 마른 빨래를 개며 상대와 주고받고 싶은 얘기는요?',array['햇볕 냄새를 색깔로 부르면 뭘지요.', '서로 유독 오래 입는 티셔츠 얘기요.', '양말 짝 찾는 나만의 요령이요.']),
  (12012,'spring',1,11,'늦봄 장터에서 작은 꽃모종 하나를 같이 고른다면 기준은요?',array['봉오리가 가장 많이 남은 걸 골라요.', '둘이 부르기 재밌는 꽃 이름을 봐요.', '햇빛이 적어도 잘 자라는지 물어요.']),
  (12051,'summer',1,0,'긴 유월 해가 퇴근 뒤에도 남으면 둘이 뭘 해 보고 싶어요?',array['하얀 벽에 길어진 손 그림자를 만들어요.', '돗자리에 앉아 늦게 뜨는 별을 기다려요.', '저녁 먹기 전에 공을 열 번 주고받아요.']),
  (12052,'summer',1,1,'손에 들고 다니던 접부채에 그림 하나를 더한다면요?',array['펴면 웃는 입이 되는 수박 조각이요.', '각자 한쪽 날개를 그린 제비요.', '접을 때 꼬리가 사라지는 물고기요.']),
  (12053,'summer',1,2,'여름을 앞두고 둘이 담근 매실청에 어떤 이름표를 달까요?',array['가을에 만나면 열어 볼 초록 약속.', '설탕 눈에 파묻힌 동그라미들.', '한 모금 먼저 웃는 사람 소원권.']),
  (12054,'summer',1,3,'여름밤 개구리 소리를 듣다 즉흥 연주를 한다면요?',array['무릎을 두드려 낮은 박자를 넣어요.', '빈 병에 바람을 불어 한 음을 보태요.', '울음이 쉬는 틈마다 휘파람을 짧게 불어요.']),
  (12055,'summer',1,4,'장마에 신발이 젖은 날을 유쾌하게 만드는 작은 대책은요?',array['발목 양말을 제일 엉뚱한 무늬로 골라요.', '마른 곳에서 빗방울 크기를 점수 매겨요.', '젖은 운동화에 각자 구조대 이름을 붙여요.']),
  (12056,'summer',1,5,'둘이서 빙수를 먹을 때 가장 마지막까지 지키고 싶은 건요?',array['바닥에 고인 달달한 우유 한 숟갈이요.', '반씩 나눠 먹을 큼직한 찹쌀떡이요.', '아무것도 묻지 않은 뽀얀 얼음 한쪽이요.']),
  (12057,'summer',1,6,'매미 소리에 서로 말이 안 들리면 뭘 해 볼까요?',array['냅킨에 지금 기분을 만화로 그려요.', '입 모양만 보고 메뉴를 맞혀요.', '잠깐 멈춰 몇 종류가 우는지 세 봐요.']),
  (12058,'summer',1,7,'시원한 도서관에 소나기가 그칠 때까지 갇히면 각자 뭘 고를까요?',array['한눈에 같이 읽을 큰 판형의 그림책이요.', '빗소리에 어울리는 시 한 편이요.', '폭염 속 다른 나라 풍경을 담은 도감이요.']),
  (12059,'summer',1,8,'잘 익은 복숭아 한 상자를 나눈다면 첫 복숭아는 어떻게 먹어요?',array['차갑게 식혀 한 입 크기로 썰어요.', '흐르는 물에 씻어 큰 접시 위에서 베어 물어요.', '둘이 각자 한 조각씩 구워 맛을 비교해요.']),
  (12060,'summer',1,9,'한밤의 열기가 식었을 때 딱 한 바퀴 걷는다면 어느 때 멈출까요?',array['바람이 도는 모퉁이를 발견했을 때요.', '얼음물 컵에 물방울이 맺힐 때요.', '길가 풀숲에서 귀뚜라미가 울 때요.']),
  (12061,'summer',1,10,'여름 바닷가에서 파도에 바로 지워질 말을 쓰면 어떤 말일까요?',array['오늘의 걱정은 여기 두고 갑니다.', '밀려오는 물결에게 앙코르 한 번 더!', '다음 파도엔 네가 이름을 붙여 줘.']),
  (12062,'summer',1,11,'여름 끝자락에 남은 얼음 틀을 색다르게 써 본다면요?',array['레몬 조각을 넣어 투명하게 얼려요.', '보리차를 얼려 묽어지지 않게 해요.', '포도 주스를 얼려 둘이 작은 빙과를 먹어요.']),
  (12101,'autumn',1,0,'첫 긴소매를 꺼낸 날 둘만의 가을 개시 신호를 만든다면요?',array['따뜻한 보리차를 따라 잔을 부딪쳐요.', '달력 한 칸에 작은 도토리를 그려요.', '소매를 쭉 펴고 손가락으로 악수해요.']),
  (12102,'autumn',1,1,'가을 운동회에서 처음 만난 둘이 한 팀이라면 어떤 구호를 외쳐요?',array['이겨도 간식, 져도 간식!', '박자는 엉켜도 결승선은 같이!', '하나, 둘, 우리 편 웃어요!']),
  (12103,'autumn',1,2,'새로 깎은 배 한 접시를 앞에 두고 먼저 고르는 조각은요?',array['아삭함을 오래 느낄 가장 두꺼운 조각이요.', '포크에 딱 맞는 조그만 끝 조각이요.', '달콤한 향이 나는 가운데 조각이요.']),
  (12104,'autumn',1,3,'높은 가을 하늘에 연을 띄울 때 둘의 역할을 어떻게 나눌까요?',array['제가 바람을 읽으면 상대가 실을 풀어요.', '번갈아 손잡이를 잡고 높이 기록을 재요.', '한 명은 달리고 한 명은 뒤에서 응원해요.']),
  (12105,'autumn',1,4,'가을 들판 풍경을 엽서에 세 가지 색만 써서 남긴다면요?',array['볏짚 노랑과 감색, 물길의 연파랑이요.', '바랜 초록과 미색, 허수아비의 빨강이요.', '노을 분홍과 흙빛, 산 그림자 보라요.']),
  (12106,'autumn',1,5,'은행잎이 노랗게 물든 날 누군가에게 건네고 싶은 안부는요?',array['네가 좋아한 노란 물감 색을 발견했어.', '올해는 단풍 구경 한 번 같이 갈래?', '노란 부채꼴 잎이 발에 따라왔어.']),
  (12107,'autumn',1,6,'가을 책 축제에서 상대에게 대신 받아 주고 싶은 선물은요?',array['나뭇잎 도장이 찍힌 종이 책갈피요.', '작가가 골라 준 뜻밖의 낱말 하나요.', '책 표지를 감싼 알록달록 돌림종이요.']),
  (12108,'autumn',1,7,'가을 산책길에서 도토리를 만났을 때 나올 법한 대화는요?',array['모자가 벗겨진 건 어디에 갔을까요?', '도토리랑 밤은 어릴 때도 닮았을까요?', '다람쥐라면 오늘 몇 알쯤 챙길까요?']),
  (12109,'autumn',1,8,'찬바람 속 호떡을 둘이 처음 먹는 사람에게 알려 줄 요령은요?',array['바로 깨물지 말고 김부터 조금 빼요.', '종이컵을 살짝 눌러 당을 퍼뜨려요.', '마지막 한 입은 컵 위에서 먹어요.']),
  (12110,'autumn',1,9,'앙상해진 나뭇가지가 만든 그림자에서 어떤 모양을 찾겠어요?',array['길을 잃은 사슴의 커다란 뿔이요.', '악보를 가득 채운 잔뜩 굽은 음표요.', '서로 다른 곳을 가리키는 작은 손이요.']),
  (12111,'autumn',1,10,'겨울 오기 전 익은 감을 말리기로 했다면 나는 무슨 담당인가요?',array['겹치지 않게 줄에 매다는 일을 해요.', '매일 색이 진해지는 걸 그림으로 남겨요.', '첫 곶감을 반 가를 기념일을 정해요.']),
  (12112,'autumn',1,11,'낙엽이 다 진 공원 벤치에서 차 한 잔 마신다면 뭘 담아 올까요?',array['뚜껑 여는 순간 향이 퍼지는 유자차요.', '바람에 식어도 구수한 옥수수차요.', '한 모금씩 나눌 작은 잔 두 개와 홍차요.']),
  (12151,'winter',1,0,'해가 일찍 지는 겨울 저녁에 창가를 꾸민다면 어떤 빛을 쓸까요?',array['종이별 안에서 새어 나오는 노란 불빛이요.', '책 사이에 숨긴 조그만 독서등이요.', '밖을 향해 한 줄로 붙이는 별 전구요.']),
  (12152,'winter',1,1,'겨울 시장에서 온기가 가득한 음식을 고를 땐 무엇부터 봐요?',array['뚜껑 열 때 김이 피어나는 찜기요.', '달각달각 뒤집는 붕어빵 틀이요.', '따끈한 국물이 담긴 커다란 주전자요.']),
  (12153,'winter',1,2,'눈사람에게 당근 코 말고 둘이 새 장식을 붙인다면요?',array['마른 솔잎 세 가닥으로 만든 콧수염이요.', '나뭇잎을 접어 만든 초록 나비넥타이요.', '눈덩이로 빚은 큼직한 귀마개요.']),
  (12154,'winter',1,3,'한 해의 마지막 우체통에 서로 보낼 한 줄은 뭐가 좋을까요?',array['올해 네 덕분에 많이 웃은 날이 있어.', '같이 못 간 곳은 다음 달 몫으로 남겨 두자.', '새 달력에도 재밌는 낙서를 해 보자.']),
  (12155,'winter',1,4,'새 달력 첫 장에 둘만 아는 작은 기념일을 넣는다면요?',array['겨울 첫 따뜻한 코코아 마신 날이요.', '손끝 시린데도 산책을 완주한 날이요.', '현관의 빈 화분에 이름을 지어 준 날이요.']),
  (12156,'winter',1,5,'꽁꽁 언 연못을 바라보며 그 아래를 상상한다면 뭐가 보일까요?',array['둥글게 모여 낮잠 자는 물고기요.', '얼음 천장에 매달린 작은 공기 방울이요.', '햇살이 바닥에 그린 반짝이는 줄무늬요.']),
  (12157,'winter',1,6,'겨울철 장갑을 낀 채 둘이 해야 한다면 뭐가 제일 웃길까요?',array['미니 귤 한 개를 반듯하게 까기요.', '콩알만 한 단추를 끝까지 채우기요.', '종이 한 장을 조그만 학으로 접기요.']),
  (12158,'winter',1,7,'매서운 바람에 뺨이 차가워진 날 상대에게 건넬 첫 잔은요?',array['김이 모락모락 나는 생강차 한 모금이요.', '거품에 입김이 닿는 뜨거운 우유요.', '무가 푹 익어 달큰한 어묵 국물이요.']),
  (12159,'winter',1,8,'겨울 끝에 얇아진 얼음의 색을 물감 두 가지로 만든다면요?',array['연한 하늘색에 우유 같은 흰색을 섞어요.', '회색 바탕에 민트색을 살짝 얹어요.', '묽은 남색에 노란빛을 한 방울 넣어요.']),
  (12160,'winter',1,9,'긴 겨울을 함께한 목도리를 넣어 두기 전 어떤 작별 인사를 해요?',array['잘 씻고 가을에 다시 만나자고 해요.', '올겨울 간 곳을 꼽아 감사장을 써요.', '가장 잘 어울린 외투랑 기념사진을 찍어요.']),
  (12161,'winter',1,10,'겨울 마지막 눈이 올 때 바깥에서 둘이 남기고 싶은 소리는요?',array['아무도 안 밟은 곳의 첫 뽀드득 소리요.', '손 털며 마주 보고 터지는 웃음소리요.', '처마 끝에서 봄처럼 녹아 톡 떨어지는 물소리요.']),
  (12162,'winter',1,11,'해가 조금 길어졌다는 걸 깨닫게 해 주는 겨울 풍경은요?',array['문 닫는 가게 유리에 노을이 비칠 때요.', '저녁밥 짓는데 창밖 하늘이 아직 파래요.', '책 읽다 조명을 늦게 켜도 될 때요.']),
  (12201,'seollal',1,0,'설 연휴를 앞두고 둘이 하나씩 내려놓고 싶은 할 일은 뭔가요?',array['읽던 책을 끝까지 읽어야 한다는 숙제요.', '휴일 일정표를 가득 채우는 일이요.', '사진을 예쁘게 보정하는 일이요.']),
  (12202,'seollal',1,1,'설맞이 작은 장을 연다면 상대를 웃게 할 가게는 뭘 팔까요?',array['새해 핑계로 늦잠 잘 권리요.', '덕담을 대신 써 주는 종이 만두요.', '까치 그림이 든 첫 산책 표요.']),
