  (12802,'liberation',1,1,'광복절에 둘이 읽은 기록을 잊지 않으려면, 어떻게 간직하고 싶나요?',array['마음에 남은 문장을 손으로 옮겨 적을래요.', '다시 읽을 수 있게 자료 이름을 남길래요.', '궁금해진 단어 하나를 더 찾아볼래요.']),
  (12851,'foundation',1,0,'개천절에 박물관에서 가장 먼저 들여다보고 싶은 옛 물건은 무엇인가요?',array['손때가 남은 작은 그릇이요.', '낯선 무늬가 그려진 옛 기와요.', '작은 조각을 이어 만든 장신구요.']),
  (12852,'foundation',1,1,'개천절에 둘이 옛 문화를 한 가지 배워 본다면 무엇이 궁금한가요?',array['전통 문양 속에 숨은 뜻이 궁금해요.', '옛사람들이 쓰던 색의 이름이요.', '한지 한 장이 만들어지는 과정이요.']),
  (12901,'memorial',1,0,'현충일에 누군가와 추모 공간을 찾는다면 어떻게 그 시간을 보내고 싶나요?',array['글을 차례차례 조용히 읽고 싶어요.', '말을 줄이고 각자 천천히 걸을래요.', '헌화한 뒤 잠시 가만히 서 있을래요.']),
  (12902,'memorial',1,1,'현충일에 읽은 글에서 오래 기억하고 싶은 부분을 어떻게 남겨 두나요?',array['일기에 이름과 날짜를 적어 둘래요.', '다시 찾아보게 자료 제목을 적어요.', '마음이 머문 한 구절을 옮겨 쓸래요.']);
